window.AP_LEARNING=window.AP_LEARNING||{};
window.AP_LEARNING["lesson-16"]={
  version:1,title:"Nutrition and the Digestive System",chapter:16,duration:"90–110 minutes",
  outcomes:["Trace food through the alimentary canal and identify accessory-organ contributions.","Relate wall layers, motility, secretion, digestion, and absorption.","Compare carbohydrate, protein, and lipid digestion without reducing food to one nutrient.","Explain why the small intestine is the main absorption site and how the colon supports fluid recovery.","Connect digestive physiology to nutrition assessment while recognizing symptoms that require medical evaluation."],
  modules:[
    {id:"organization",title:"Orient to the digestive tube",summary:"Build the wall layers, movement pattern, and oral phase before following individual nutrients.",moments:[
      {id:"l16-m1",title:"One continuous tube, four repeating wall layers",highYield:"Mucosa handles contact and absorption; submucosa supports; muscularis moves; serosa/adventitia anchors or reduces friction.",teaching:["The alimentary canal runs from mouth to anus. Although each region is specialized, much of the tube follows a four-layer plan: mucosa, submucosa, muscularis externa, and an outer serosa or adventitia. The mucosa includes epithelium, connective tissue, and a thin muscle layer; its surface changes according to function.","The submucosa carries vessels, glands, and nerve networks. Circular and longitudinal smooth muscle in the muscularis mix and propel contents. Enteric nerve plexuses coordinate local activity while autonomic and hormonal signals modify it. Digestion is therefore mechanical, chemical, and regulatory at the same time."],keyPoints:["Mucosa faces the lumen.","Submucosa supports vessels, glands, and nerves.","Muscularis mixes and propels.","Serosa reduces friction; adventitia anchors some regions."],visual:{title:"GI wall from lumen outward",kind:"layers",items:[{label:"Mucosa",detail:"Secretion, protection, absorption"},{label:"Submucosa",detail:"Vessels, glands, connective support, nerve plexus"},{label:"Muscularis externa",detail:"Circular and longitudinal movement"},{label:"Serosa/adventitia",detail:"Outer covering or attachment"}]},mnemonic:{title:"M-S-M-S",cue:"Mucosa · Submucosa · Muscularis · Serosa",explanation:"Move from the lumen outward; substitute adventitia where the organ is anchored."},goodToKnow:"The enteric nervous system can coordinate local reflexes, but it still communicates with the central nervous and endocrine systems.",practiceConnection:"Symptoms can arise from motility, secretion, inflammation, obstruction, absorption, or several processes together; avoid treating every complaint as a food intolerance.",activity:{prompt:"Which layer directly contacts material in the intestinal lumen?",options:[{text:"Mucosa",correct:true,feedback:"Correct. Its epithelium forms the luminal surface."},{text:"Muscularis externa",correct:false,feedback:"The muscularis lies deeper and produces movement."},{text:"Serosa",correct:false,feedback:"The serosa is an outer covering."}]}},
      {id:"l16-m2",title:"The mouth begins both processing and decision-making",highYield:"Chewing, saliva, tongue movement, and swallowing prepare a manageable bolus; digestion does not begin in the stomach.",teaching:["Teeth mechanically reduce food size, increasing surface area. The tongue positions food, contributes to taste, and forms a bolus. Saliva moistens and lubricates, buffers the oral environment, and contains enzymes that begin starch and some lipid processing, although most digestion occurs later.","Swallowing begins voluntarily and then becomes a coordinated reflex moving the bolus through pharynx and esophagus. Peristaltic waves propel it toward the stomach while sphincters help direct flow. Chewing time or saliva alone cannot determine nutrient absorption, but oral function can strongly affect what a person can comfortably eat."],keyPoints:["Mastication increases surface area.","Saliva lubricates and begins chemical digestion.","The tongue forms and positions the bolus.","Swallowing changes from voluntary to reflex control."],visual:{title:"Oral-to-esophageal sequence",kind:"sequence",items:[{label:"Chew",detail:"Mechanical breakdown"},{label:"Moisten",detail:"Saliva lubricates and buffers"},{label:"Form bolus",detail:"Tongue organizes material"},{label:"Swallow",detail:"Pharyngeal reflex protects airway and directs bolus"},{label:"Peristalsis",detail:"Esophagus propels toward stomach"}]},mnemonic:{title:"CMFSP",cue:"Chew · Moisten · Form · Swallow · Propel",explanation:"A five-step oral and esophageal route."},goodToKnow:"Salivary amylase starts starch digestion but is not responsible for completing carbohydrate digestion.",practiceConnection:"Dental pain, dry mouth, swallowing difficulty, and limited chewing capacity can reduce intake quality and safety; they deserve direct assessment, not simply a better meal plan.",activity:{prompt:"What is the main immediate benefit of chewing for digestion?",options:[{text:"It reduces particle size and increases surface area",correct:true,feedback:"Correct. This improves contact with fluids and enzymes."},{text:"It absorbs all nutrients through the teeth",correct:false,feedback:"Teeth mechanically process food; they do not absorb nutrients."},{text:"It converts protein directly into glucose",correct:false,feedback:"Protein digestion requires enzymatic steps in the stomach and small intestine."}]}}
    ]},
    {id:"upper-organs",title:"Coordinate stomach and accessory organs",summary:"Separate storage, acid and enzymes, pancreatic secretion, bile, and liver processing.",moments:[
      {id:"l16-m3",title:"The stomach stores, mixes, acidifies, and meters",highYield:"The stomach begins substantial protein digestion and delivers chyme gradually; it is not the main nutrient-absorption site.",teaching:["The stomach's folds allow expansion while muscular layers churn food into chyme. Parietal cells secrete hydrochloric acid and intrinsic factor, chief cells release pepsinogen, and mucous cells help protect the lining. Acid denatures proteins and activates pepsin, while intrinsic factor later supports vitamin B12 absorption in the ileum.","Pyloric control meters chyme into the duodenum. Emptying rate changes with meal composition, particle size, and regulatory signals. Fat and high energy density often slow emptying, but individual symptoms are not a direct readout of one nutrient or of stomach acid level."],keyPoints:["Acid denatures protein and activates pepsin.","Intrinsic factor is required for normal B12 absorption.","Mucus and bicarbonate protect the stomach lining.","The pylorus regulates delivery to duodenum."],visual:{title:"Gastric cell roles",kind:"comparison",items:[{label:"Parietal cell",detail:"Hydrochloric acid and intrinsic factor"},{label:"Chief cell",detail:"Pepsinogen precursor"},{label:"Mucous cell",detail:"Protective mucus and local buffering"},{label:"Muscle layers",detail:"Mix chyme and support emptying"}]},mnemonic:{title:"A-I-P-M",cue:"Acid · Intrinsic factor · Pepsin · Mucus",explanation:"Four gastric products/functions to keep distinct."},goodToKnow:"Very little macronutrient absorption occurs in the stomach; most absorption occurs in the small intestine.",practiceConnection:"Persistent pain, vomiting, black stools, difficulty swallowing, or unexplained weight change require clinical evaluation rather than self-directed acid or elimination regimens.",activity:{prompt:"Which stomach product is essential for efficient vitamin B12 absorption later in the ileum?",options:[{text:"Intrinsic factor",correct:true,feedback:"Correct. B12 binds intrinsic factor before receptor-mediated absorption."},{text:"Bile",correct:false,feedback:"Bile is produced by the liver and aids lipid handling."},{text:"Insulin",correct:false,feedback:"Insulin is an endocrine pancreatic hormone, not a gastric product."}]}},
      {id:"l16-m4",title:"Pancreas, liver, and gallbladder deliver complementary support",highYield:"Pancreas supplies bicarbonate and enzymes; liver makes bile and processes portal blood; gallbladder stores and concentrates bile.",teaching:["The exocrine pancreas delivers bicarbonate to neutralize acidic chyme and enzymes that digest carbohydrate, protein, fat, and nucleic acids. Its endocrine islets release hormones such as insulin and glucagon into blood. Exocrine and endocrine functions share an organ but use different ducts and destinations.","The liver produces bile, processes portal nutrients, stores selected fuels and vitamins, synthesizes many plasma proteins, and modifies wastes and chemicals. The gallbladder stores and concentrates bile, then releases it when signalled. Bile emulsifies fat into smaller droplets; it is not a digestive enzyme and does not chemically split triglycerides."],keyPoints:["Pancreatic bicarbonate raises duodenal pH.","Pancreatic enzymes act on all major nutrient classes.","Liver produces bile; gallbladder stores it.","Bile emulsifies rather than hydrolyzes fat."],visual:{title:"Accessory-organ teamwork",kind:"map",items:[{label:"Pancreas",detail:"Bicarbonate plus digestive enzymes"},{label:"Liver",detail:"Bile production and portal processing"},{label:"Gallbladder",detail:"Bile storage and concentration"},{label:"Duodenum",detail:"Receives chyme, bile, and pancreatic secretion"}]},mnemonic:{title:"PBLG",cue:"Pancreas breaks · Bile bundles · Liver generates · Gallbladder holds",explanation:"A compact cue; remember enzymes break bonds while bile disperses fat."},goodToKnow:"A person can live without a gallbladder because the liver still produces bile, though delivery becomes less concentrated and less meal-timed.",practiceConnection:"Nutrition strategies after pancreatic, liver, or gallbladder disease must reflect diagnosis and clinical plan; generic 'detox' language obscures the actual physiology.",activity:{prompt:"Which statement about bile is accurate?",options:[{text:"It emulsifies fat, increasing surface area for lipase",correct:true,feedback:"Correct. Bile disperses fat droplets but does not hydrolyze triglycerides itself."},{text:"It is a protease secreted by the stomach",correct:false,feedback:"Bile is not an enzyme and is produced by the liver."},{text:"It transports oxygen in red blood cells",correct:false,feedback:"Hemoglobin performs that role."}]}}
    ]},
    {id:"intestinal",title:"Digest and absorb",summary:"Use small-intestinal surface area and colon function to explain nutrient and fluid handling.",moments:[
      {id:"l16-m5",title:"The small intestine completes digestion and captures nutrients",highYield:"Folds, villi, and microvilli create a large absorptive surface supplied by blood capillaries and lacteals.",teaching:["The duodenum receives chyme, bile, and pancreatic secretion; the jejunum is a major site of absorption; and the ileum completes absorption of selected substances, including the intrinsic-factor–B12 complex and recycled bile salts. Segmentation mixes contents while peristalsis advances them.","Circular folds, villi, and microvilli multiply surface area. Monosaccharides, amino acids, and many water-soluble products enter blood capillaries and travel through the hepatic portal vein. Long-chain lipids are rebuilt into triglycerides, packaged into chylomicrons, and enter lacteals before reaching blood."],keyPoints:["Duodenum coordinates neutralization and digestion.","Villi and microvilli expand surface area.","Water-soluble nutrients generally enter portal blood.","Chylomicrons generally enter lymphatic lacteals."],visual:{title:"Two absorption routes",kind:"comparison",items:[{label:"Blood capillary route",detail:"Monosaccharides, amino acids, many minerals and water-soluble vitamins → portal vein"},{label:"Lacteal route",detail:"Chylomicrons containing long-chain dietary lipid → lymph → venous blood"},{label:"Ileal specialities",detail:"B12–intrinsic factor complex and bile-salt recovery"}]},mnemonic:{title:"Sugar and amino acids sail portal; fat floats lymph",cue:"Portal for soluble · lymph for chylomicrons",explanation:"A useful general pattern with exceptions for some shorter fatty acids."},goodToKnow:"Absorption is selective and transporter-dependent; eating a nutrient does not guarantee identical absorption in every context.",practiceConnection:"Bioavailability depends on food form, meal interactions, gut health, surgery, medicines, and need. A food record alone cannot prove absorption.",activity:{prompt:"Where do most long-chain dietary lipids go immediately after absorption?",options:[{text:"Into chylomicrons that enter intestinal lacteals",correct:true,feedback:"Correct. They travel through lymph before venous blood."},{text:"Directly into the aorta as free triglycerides",correct:false,feedback:"They are packaged in enterocytes and enter lymph first."},{text:"Into the urinary bladder",correct:false,feedback:"The urinary tract is not an absorption route for dietary lipid."}]}},
      {id:"l16-m6",title:"The large intestine recovers fluid and forms stool",highYield:"The colon reabsorbs water and electrolytes, houses microbes, compacts contents, and coordinates elimination.",teaching:["Material entering the large intestine contains water, electrolytes, undigested components, microbes, shed cells, and secretions. The colon absorbs much of the remaining water and electrolytes, secretes mucus, and moves contents through haustral mixing and mass movements toward the rectum.","Colonic microbes ferment selected carbohydrates and produce metabolites, including short-chain fatty acids, while also contributing to some vitamin production. Microbiome composition varies widely; one stool pattern cannot define a 'healthy microbiome,' and broad claims about cleansing or toxins are not supported by colon anatomy."],keyPoints:["Colon recovers water and electrolytes.","Mucus supports passage.","Microbes ferment selected substrates.","Rectal filling participates in the defecation reflex."],visual:{title:"Colon functions",kind:"map",items:[{label:"Recover",detail:"Water and electrolytes"},{label:"Ferment",detail:"Microbial use of selected carbohydrates"},{label:"Compact",detail:"Formation of fecal material"},{label:"Propel",detail:"Movement toward rectum and elimination"}]},mnemonic:{title:"RFCP",cue:"Recover · Ferment · Compact · Propel",explanation:"Four colon functions without calling it a waste-storage tube only."},goodToKnow:"Stool frequency varies; a change from a person's usual pattern plus symptoms is often more informative than one universal number.",practiceConnection:"Fibre, fluid, movement, medicines, pelvic-floor function, and disease can all affect bowel patterns. Persistent bleeding, severe pain, obstruction signs, or major change needs assessment.",activity:{prompt:"Which is a major function of the large intestine?",options:[{text:"Recovery of water and electrolytes",correct:true,feedback:"Correct. The colon helps conserve fluid while forming stool."},{text:"Production of pancreatic enzymes",correct:false,feedback:"Those enzymes come from the pancreas."},{text:"Most amino-acid absorption",correct:false,feedback:"Most nutrient absorption occurs in the small intestine."}]}}
    ]},
    {id:"nutrient-integration",title:"Connect foods to pathways",summary:"Follow macronutrient digestion and use a scoped, evidence-aware nutrition lens.",moments:[
      {id:"l16-m7",title:"Each macronutrient needs a different breakdown strategy",highYield:"Carbohydrate becomes absorbable monosaccharides, protein becomes amino acids and small peptides, and triglyceride becomes lipid products before repackaging.",teaching:["Starch digestion begins with amylase and is completed by pancreatic and brush-border enzymes to monosaccharides. Protein is denatured in the stomach and hydrolyzed by gastric, pancreatic, and brush-border proteases into amino acids and small peptides. These products use specific transport systems to enter enterocytes and then portal blood.","Fat requires emulsification by bile and hydrolysis mainly by pancreatic lipase. Lipid products form micelles that approach the enterocyte membrane, then are absorbed, reassembled, and packaged into chylomicrons. The pathway explains why bile and pancreatic function matter without implying that dietary fat is inherently difficult or harmful."],keyPoints:["Starch → monosaccharides.","Protein → amino acids and small peptides.","Triglycerides → fatty acids/monoglycerides → reassembly.","Transporters and packaging complete absorption."],visual:{title:"Macronutrient pathways",kind:"comparison",items:[{label:"Carbohydrate",detail:"Amylases and brush-border enzymes → monosaccharides → portal blood"},{label:"Protein",detail:"Pepsin and pancreatic/brush-border proteases → amino acids/peptides → portal blood"},{label:"Fat",detail:"Bile + lipase → micelles → enterocyte → chylomicron → lymph"}]},mnemonic:{title:"C-P-F: Cut, Process, Ferry",cue:"Cut bonds · Process at brush border · Ferry through blood or lymph",explanation:"Use the same logic while keeping each nutrient's products and route distinct."},goodToKnow:"Fibre is not digested into glucose by human enzymes; fermentable fibre can be metabolized by colonic microbes.",practiceConnection:"Symptoms after a meal do not identify which digestive stage failed. Timing, dose, preparation, pattern, and clinical history all matter.",activity:{prompt:"Which pairing is correct?",options:[{text:"Bile emulsifies lipid; pancreatic lipase hydrolyzes triglyceride",correct:true,feedback:"Correct. Physical dispersion and chemical digestion are different jobs."},{text:"Pepsin digests starch into glucose",correct:false,feedback:"Pepsin is a protease."},{text:"Amylase converts protein into amino acids",correct:false,feedback:"Amylase acts on starch."}]}},
      {id:"l16-m8",title:"Assessment separates intake, digestion, absorption, and use",highYield:"A nutrient problem can arise before eating, during digestion, at absorption, in transport, or during cellular use.",teaching:["Nutritional status is not determined by intake alone. Food access and appetite affect intake; oral and GI function affect digestion; mucosal surface and transporters affect absorption; liver and circulation affect distribution; and cells must use or store what arrives. Losses and altered needs add further branches.","This pathway keeps counselling focused. Ask what the person eats, what happens after eating, how long the pattern has persisted, what medical evaluation exists, and which practical barriers matter. Avoid diagnosing malabsorption or prescribing restrictive diets from symptoms alone."],keyPoints:["Availability precedes intake.","Digestion and absorption are distinct.","Transport and cellular use follow absorption.","Losses and needs change status."],visual:{title:"Nutrition status pathway",kind:"flow",items:[{label:"Available",detail:"Food access and feasibility"},{label:"Consumed",detail:"Appetite, chewing, swallowing"},{label:"Digested",detail:"Mechanical and enzymatic breakdown"},{label:"Absorbed",detail:"Movement across gut epithelium"},{label:"Used/stored",detail:"Transport, metabolism, and reserves"}]},mnemonic:{title:"A-C-D-A-U",cue:"Available · Consumed · Digested · Absorbed · Used",explanation:"Locate the possible bottleneck before choosing an intervention."},goodToKnow:"A normal-looking diet does not rule out impaired absorption, and GI symptoms do not prove malabsorption.",practiceConnection:"Coordinate care when there is persistent vomiting, blood in stool, severe pain, progressive swallowing difficulty, dehydration, jaundice, or unexplained weight loss.",activity:{prompt:"A client eats adequate B12 but has impaired intrinsic-factor production. Which stage is most directly affected?",options:[{text:"Absorption",correct:true,feedback:"Correct. Intake may be adequate while ileal B12 uptake is impaired."},{text:"Food availability",correct:false,feedback:"The nutrient is available and consumed in this example."},{text:"Chewing",correct:false,feedback:"The mechanism described is not oral processing."}]}}
    ]}
  ],
  caseStudy:{title:"A restrictive diet built from symptoms alone",scenario:"A client reports bloating, intermittent diarrhea, fatigue, and an unplanned weight change. They have removed gluten, dairy, legumes, fruit, and several vegetables after online advice, but symptoms continue. No diagnostic evaluation has occurred.",prompts:["Which stages of the nutrition-status pathway could contribute?","Which red flags or duration details should be clarified?","How might broad restriction create additional nutrition risk?","What can be documented and supported while medical assessment proceeds?"],takeaway:"GI symptoms rarely identify one mechanism by themselves. Protect intake, document the pattern, avoid escalating unsupported restrictions, and coordinate appropriate assessment."},
  recap:["The alimentary canal follows a repeating four-layer plan.","Mechanical and chemical digestion begin in the mouth.","The stomach mixes, acidifies, begins protein digestion, and meters chyme.","Pancreas provides bicarbonate and enzymes; liver makes bile; gallbladder stores it.","The small intestine completes most digestion and absorption.","The colon recovers fluid, supports microbial fermentation, and forms stool.","Nutrition status depends on availability, intake, digestion, absorption, transport, use, losses, and need."],
  flashcards:[{front:"Mucosa",back:"The innermost GI layer responsible for protection, secretion, and absorption.",tag:"wall"},{front:"Peristalsis",back:"Coordinated wave-like contraction that propels contents along the digestive tract.",tag:"motility"},{front:"Intrinsic factor",back:"A gastric protein required for efficient vitamin B12 absorption in the ileum.",tag:"stomach"},{front:"Pepsin",back:"A gastric protease activated in acidic conditions that begins protein digestion.",tag:"stomach"},{front:"Bile",back:"A liver secretion that emulsifies lipid and supports micelle formation; it is not an enzyme.",tag:"accessory"},{front:"Pancreatic bicarbonate",back:"An alkaline secretion that helps neutralize acidic chyme in the duodenum.",tag:"accessory"},{front:"Villus",back:"A projection of small-intestinal mucosa containing blood capillaries and a lacteal.",tag:"absorption"},{front:"Chylomicron",back:"A lipoprotein particle carrying absorbed long-chain dietary lipid from enterocyte into lymph.",tag:"absorption"},{front:"Hepatic portal vein",back:"Vessel delivering blood from digestive organs to the liver before systemic return.",tag:"absorption"},{front:"Segmentation",back:"Local intestinal mixing contractions that expose contents to enzymes and absorptive surfaces.",tag:"motility"},{front:"Colon",back:"Large-intestinal region that recovers water/electrolytes, houses microbes, and compacts stool.",tag:"colon"},{front:"Bioavailability",back:"The fraction of an ingested substance that becomes available for absorption and use, shaped by food and host factors.",tag:"nutrition"}],
  practice:[{prompt:"List the four common GI wall layers from lumen outward.",answer:"Mucosa, submucosa, muscularis externa, and serosa/adventitia.",rationale:"The repeating plan helps compare organs.",tag:"wall"},{prompt:"What does chewing contribute?",answer:"It reduces particle size, increases surface area, and helps form a swallowable bolus.",rationale:"Mechanical processing supports later enzymatic contact.",tag:"oral"},{prompt:"Name two parietal-cell products.",answer:"Hydrochloric acid and intrinsic factor.",rationale:"They support protein digestion and B12 absorption respectively.",tag:"stomach"},{prompt:"Distinguish bile from lipase.",answer:"Bile emulsifies lipid physically; lipase hydrolyzes triglyceride chemically.",rationale:"They are complementary but not interchangeable.",tag:"fat"},{prompt:"Where are most nutrients absorbed?",answer:"The small intestine.",rationale:"Its folds, villi, microvilli, vessels, and transporters create a large absorptive interface.",tag:"absorption"},{prompt:"Which absorbed particles enter lacteals?",answer:"Chylomicrons carrying long-chain dietary lipid.",rationale:"They are too large for direct entry into ordinary blood capillaries.",tag:"absorption"},{prompt:"What are two major colon functions?",answer:"Water/electrolyte recovery and formation/propulsion of stool; microbial fermentation is another.",rationale:"The colon is active, not merely storage.",tag:"colon"},{prompt:"Why does eating a nutrient not prove it was absorbed?",answer:"Digestion, mucosal integrity, transporters, interactions, and disease can change absorption.",rationale:"Intake and status are separate steps.",tag:"nutrition"},{prompt:"Place ACDAU in order.",answer:"Available, consumed, digested, absorbed, used/stored.",rationale:"The pathway locates where a nutrition problem may arise.",tag:"nutrition"},{prompt:"Why is broad elimination risky without assessment?",answer:"It may reduce energy, protein, fibre, micronutrients, variety, and quality of life without addressing the cause.",rationale:"Restriction has costs and symptoms alone may not identify the trigger.",tag:"practice"}]
};
